/// <summary>
/// An Expression Class used to translate a given label to the current language.
/// </summary>
[TFMDescription("An Expression Class used to translate a given label to the current language. Takes Label Id as input.")]
class TFMExpressionsLabel extends TFMExpressions
{

}

