[SysObsolete]
public str processExpressionCommon(Common _common)
{
    str ret;


    return ret;
}

public str processExpressionValue(str _value, TFMLocalizedStringEDT _localizedString = '')
{
    TFMTranslations translations;
    LabelString     lblString = _value;
    str             ret;

    if(_localizedString)
    {
        return TFMTranslations::GetTranslatedValue(_localizedString, currentUserLanguage());
    }
    else if(_value)
    {
        ret = SysLabel::isLabelId(_value) ? SysLabel::labelId2String(_value,new xInfo().language()) : _value;
    }

    return ret;
}
